// CSD_RATIONALE_BEGIN
// Root cause analysis after reviewing the full attempt ledger (attempts 40–73):
//
// Attempt 72 (best: 53.3%) used CloseSpanWithinBudget(400) + guidance
//   "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY
//    the exact table and column names from the provided schema. No aliases."
// Attempt 73 (48.0%): Replaced simple format guidance with prescriptive SQL rules
//   (INTERSECT, COUNT(DISTINCT), "do not repeat conditions") → REGRESSION.
// Conclusion: The model degrades when guidance tries to teach SQL semantics rather
//   than just specifying the output format. The model's SQL reasoning is better
//   left alone; the guidance should only anchor format and column discipline.
//
// Observed failure modes in the 156 wrong examples:
//   (1) Wrong aggregation: "SELECT MAX(flightno)" instead of GROUP BY + ORDER BY
//       COUNT(*) DESC LIMIT 1. The airport query is a canonical example.
//   (2) Column hallucination: "SELECT DISTINCT col1, col2, col3 ... col100"
//       The model selects all reachable columns rather than the 1 asked for.
//   (3) Semantically close but evaluated wrong (e.g., subquery-IN vs JOIN+OR).
//
// Fix: Restore attempt 72's structure exactly (preamble=5, budget=400) but refine
//   guidance to add one concrete pattern hint for aggregation (fixing failure 1)
//   and one column-count constraint (fixing failure 2) WITHOUT adding the confusing
//   INTERSECT/COUNT(DISTINCT)/repeat rules that caused the attempt 73 regression.
//   Format guidance must remain primary; semantic hints are secondary and minimal.
//
// Budget math: 5 (preamble) + 1 (force-<<) + 400 (constrained+close) = 406 << 900.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the implication
//   is vacuously true on every iteration. The only true-flip occurs via
//   RenderedEndsWith(generated, "<<"), at which point we set
//   currentConstrainedOut := []; parser.IsValidPrefix([]) holds by the method
//   precondition requires parser.IsValidPrefix([]). EOS break leaves
//   insideConstrainedOut false (vacuous).
//
// Phase 2 OpenConstrainedSpan: Runs only when !insideConstrainedOut.
//   Postcondition guarantees currentConstrainedOut := [] (parser-valid by
//   precondition) and insideConstrainedOut := true. Invariant satisfied.
//
// Phase 3 CloseSpanWithinBudget: Postcondition directly guarantees both
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//   Both closed and still-open exit paths satisfy the invariant.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs exactly 1 step. On EOS path: no append,
//   steps += 1, bound preserved. On non-EOS path: |generated| += 1, steps += 1
//   (1:1). RenderedEndsWith branch only updates span state.
//
// Phase 2: OpenConstrainedSpan appends exactly one "<<" token and costs 1 step.
//   steps += 1, |generated| += 1. Bound preserved at exact 1:1 ratio.
//
// Phase 3: closeBudget = min(maxSteps - steps_before, 400) <= maxSteps - steps_before.
//   CloseSpanWithinBudget postcondition: |cg| <= |generated| + closeBudget.
//   We assign steps += closeBudget, so |cg| <= |generatedPrefix| + new_steps.
//   Tokens consumed by dead-end avoidance or EOS but not appended visibly still
//   count against closeBudget; visible output growth is bounded by closeBudget.
//
// cost = steps <= maxSteps: closeBudget <= maxSteps - steps_before ensures
//   steps_before + closeBudget <= maxSteps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a complete valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. SELECT only the 1-3 columns the question directly asks for. For questions about 'which X has the most/least', use: SELECT x FROM t GROUP BY x ORDER BY COUNT(*) DESC LIMIT 1. No explanation, no markdown, no aliases not in the schema. The SQL must go between << and >>.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if the model did not emit it naturally
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3+4: Generate full SQL and close span via CloseSpanWithinBudget(400).
// Budget=400 lets CloseSpanWithinBudget explore forward and track the LONGEST
// complete SQL parse (including WHERE/JOIN/GROUP BY/ORDER BY clauses), not just
// the first minimal completion ("SELECT col FROM table"). This was validated as
// better than budget=250 (attempt 72: 53.3% vs attempt 73: 48.0%).
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 400 {
    closeBudget := remaining;
  } else {
    closeBudget := 400;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

